  [429303] = { "Deep Freezeのアビリティを得ます：\n\n$I1\n$D1の間、対象をスタンさせます。Frozen状態の対象にのみ使用できます。Stunを永続的に無効化する対象には$N2のダメージを与えます。このダメージはGlaciateのスタックの恩恵を受けますが、スタックを消費しません。", nil, 0xd3f53482, nil, "um" },
  [429304] = { "頭部にDeep Freezeのルーンを刻みます：\n\n$I1\n対象を$D1の間スタンさせます。Frozen状態の対象にのみ使用可能です。Stunに永続的な耐性を持つ対象には$N2のダメージを与えます。このダメージはGlaciateのスタックの恩恵を受けますが、スタックを消費しません。", nil, 0xee3fd969, nil, "um" },
  [429305] = { "Temporal Anomalyのアビリティを得ます：\n\n$I1\n時間のエネルギーの球を放ちます。球はゆっくりと前進し、$D1ごとに近くのすべてのパーティーメンバーに、$D2の間$N2のダメージを吸収するシールドを与えます。パーティーメンバーが球の近くにとどまると、このシールドの吸収量はさらに蓄積します。", nil, 0x950f9c71, nil, "um" },
  [429306] = { "頭部にTemporal Anomalyのルーンを刻みます：\n\n$I1\n時のエネルギーのオーブを放ちます。オーブはゆっくりと前進し、$D1ごとに近くのパーティーメンバー全員に、$N2のダメージを吸収するシールドを$D2の間付与します。パーティーメンバーがオーブの近くに留まると、このシールドの吸収量はさらに蓄積されます。", nil, 0x463a9f72, nil, "um" },
  [429307] = { "Molten Armorのアビリティを得ます：\n\n$I1\n攻撃を受けると$N1のFireダメージを与え、呪文クリティカル率を$N2%上昇させ、クリティカルヒットを受ける確率を$N3%減少させます。メイジに同時に有効にできるアーマーの呪文は一種類だけです。$D1持続します。", nil, 0xa5a12b27, nil, "um" },
