  [429309] = { "手首にDisplacementのルーンを刻みます：\n\n$I1\n最後にBlinkを使った地点に戻り、Blinkのクールダウンをリセットします。Blink使用後$D1以内にのみ使用可能です。", nil, 0x19928642, nil, "um" },
